css:
.section_contact-hero{position:relative;overflow-x:clip;overflow-y:clip;padding-bottom:clamp(150px,14vw,200px)}
.ab_ct-dish{position:absolute;right:-12vw;top:clamp(80px,7vw,120px);z-index:2;width:min(42vw,700px);aspect-ratio:0.8333;pointer-events:none}
.ab_ct-scope{position:absolute;left:0;right:0;bottom:clamp(28px,3.4vw,52px);z-index:3;height:clamp(70px,8vw,110px);border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);pointer-events:none}
.ab_dbh.is-contact{padding-bottom:0}
.ab_ct-grid{position:relative;z-index:4;display:grid;grid-template-columns:minmax(240px,330px) minmax(0,600px);grid-template-areas:"copy copy" "side form";align-items:start;grid-column-gap:clamp(24px,3vw,44px);grid-row-gap:clamp(22px,2.6vw,34px)}
.ab_ct-copy{position:relative;grid-area:copy}
.ab_dbh_eyebrow.text-style-mono.is-contact{margin-top:clamp(26px,3.4vw,48px)}
.ab_dbh_title.is-contact{margin-top:clamp(10px,1.2vw,16px)}
.ab_ct-side{position:relative;grid-area:side}
.ab_dbh_sum.is-contact{max-width:34ch;margin-top:4px;font-size:clamp(17px,1.35vw,19px)}
.ab_ct-steps{margin-top:22px;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair)}
.ab_ct-step{display:flex;grid-row-gap:14px;grid-column-gap:14px;padding-top:11px;padding-bottom:11px;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);font-size:15px;color:var(--_color---text--secondary)}
.ab_ct-step_no{min-width:26px;padding-top:3px;font-size:11px;font-weight:500;letter-spacing:0.1em;color:var(--_color---brand--signal)}
.ab_ct-form{position:relative;grid-area:form;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair);background-color:var(--_color---neutral--glass)}
.ab_ct-form_head{display:flex;justify-content:space-between;align-items:center;grid-row-gap:12px;grid-column-gap:12px;padding-top:10px;padding-right:16px;padding-bottom:10px;padding-left:16px;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);font-size:11px;letter-spacing:0.12em;text-transform:uppercase;color:var(--_color---text--tertiary)}
.ab_ct-form_ch{display:flex;align-items:center}
.ab_ct-dot{display:inline-block;width:8px;height:8px;margin-right:8px;border-top-left-radius:50%;border-top-right-radius:50%;border-bottom-right-radius:50%;border-bottom-left-radius:50%;background-color:var(--_color---brand--signal)}
.ab_ct-form_chn{margin-left:6px;color:var(--_color---text--primary);font-weight:500}
.ab_ct-meter{display:flex;align-items:flex-end;grid-row-gap:3px;grid-column-gap:3px}
.ab_ct-stations{display:none}
.ab_ct-station{position:relative}
.ab_ct-station_k{position:relative}
.ab_ct-station_l{position:relative}
.ab_ct-station_ph{position:relative}
.ab_ct-station_hint{position:relative}
.ab_ct-link{color:var(--_color---text--primary)}
@media screen and (max-width: 991px) {
.ab_ct-grid{grid-template-columns:minmax(0,600px);grid-template-areas:"copy" "side" "form"}
.ab_dbh_sum.is-contact{max-width:44ch}
.ab_ct-steps{display:none}
.ab_ct-dish{right:-14vw;width:min(56vw,620px)}
}
@media screen and (max-width: 767px) {
.ab_ct-grid{grid-template-columns:minmax(0,1fr)}
.ab_ct-dish{right:-30vw;top:70px;width:78vw;opacity:0.55}
}
